import threading
import time
from collections import OrderedDict
from functools import wraps
from typing import Any, Callable, Dict, Hashable, Optional, TypeVar

T = TypeVar("T")
K = TypeVar("K", bound=Hashable)

class LRUCache:
    """Thread-safe LRU cache with per-entry TTL expiry."""

    def __init__(self, maxsize: int = 128, ttl: float = 60.0) -> None:
        if maxsize < 1:
            raise ValueError("maxsize must be >= 1")
        if ttl <= 0:
            raise ValueError("ttl must be > 0")
        self.maxsize = maxsize
        self.ttl = ttl
        self._data: "OrderedDict[K, tuple[Any, float]]" = OrderedDict()
        self._lock = threading.RLock()

    def _expired(self, expires_at: float) -> bool:
        return time.monotonic() >= expires_at

    def get(self, key: K) -> Optional[Any]:
        """Return a cached value if present and not expired."""
        with self._lock:
            item = self._data.get(key)
            if item is None:
                return None
            value, expires_at = item
            if self._expired(expires_at):
                del self._data[key]
                return None
            self._data.move_to_end(key)
            return value

    def set(self, key: K, value: Any, ttl: Optional[float] = None) -> None:
        """Store a value, evicting the least recently used entry if needed."""
        ttl_value = self.ttl if ttl is None else ttl
        if ttl_value <= 0:
            raise ValueError("ttl must be > 0")
        with self._lock:
            self._data[key] = (value, time.monotonic() + ttl_value)
            self._data.move_to_end(key)
            while len(self._data) > self.maxsize:
                self._data.popitem(last=False)

    def get_or_set(self, key: K, factory: Callable[[], Any], ttl: Optional[float] = None) -> Any:
        """Return cached value or compute, store, and return it."""
        cached = self.get(key)
        if cached is not None:
            return cached
        value = factory()
        self.set(key, value, ttl=ttl)
        return value

    def clear(self) -> None:
        """Remove all entries."""
        with self._lock:
            self._data.clear()

    def __len__(self) -> int:
        with self._lock:
            self._purge_expired()
            return len(self._data)

    def _purge_expired(self) -> None:
        expired = [k for k, (_, exp) in self._data.items() if self._expired(exp)]
        for k in expired:
            del self._data[k]

def lru_cache(maxsize: int = 128, ttl: float = 60.0) -> Callable[[Callable[..., T]], Callable[..., T]]:
    """Decorator caching function results by arguments with LRU eviction and TTL."""
    def decorator(func: Callable[..., T]) -> Callable[..., T]:
        cache = LRUCache(maxsize=maxsize, ttl=ttl)

        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> T:
            key = (args, tuple(sorted(kwargs.items())))
            return cache.get_or_set(key, lambda: func(*args, **kwargs))

        wrapper.cache = cache  # type: ignore[attr-defined]
        return wrapper

    return decorator
